package hu.vrg.mobile.core

import org.json.JSONArray
import org.json.JSONObject
import java.net.URI

// Alkalmazások (WP M21): the Desktop's in-shell HTML apps on the phone, the rules of the phone's side.
//
// Which apps, which page, which folders: DeskApps.kt, generated by Mobile/catalogue/desk-gen.js from the Desktop's own catalog
// (catalog.js appTarget: the app's folder + shared/, a repo-root page alone).
// What may be served: AppScheme.decide, a port of Dashboard/shell/lib/appscheme.js decide() (AppsTest mirrors wp-43.test.js). On the
// phone every app has its own https origin, https://<id>.appassets.androidplatform.net/, answered by the WebView's request intercept,
// so localStorage works and stays the app's own (the Desktop: vrg-app://<id>/). The app's saved data lives in that origin's storage:
// the origin must never change.
// Where the files come from: GitHub main through the contents API, like M18 Archívum. AppSync lists the folders of the files the phone
// keeps, compares git blob shas and downloads only what changed; the copies stay on the phone, so an app opens offline.

/** One app: its catalog id (= its origin), its name, the repo path of its page, the repo folders (or files) it may read. */
data class DeskApp(val id: String, val hu: String, val page: String, val allow: List<String>) {
    /** The page's folder, "" at the repo root. */
    val pageDir: String get() = page.substringBeforeLast('/', "")
}

/** decide()'s answer: serve [rel] (repo-relative) with [type], or refuse with [status] and [why]. */
data class AppDecision(val ok: Boolean, val status: Int = 200, val why: String = "", val rel: String = "", val type: String = "", val id: String = "")

object AppScheme {
    /** The apps' parent domain; WebViewAssetLoader's reserved one, never on the network. */
    const val DOMAIN = "appassets.androidplatform.net"

    val TYPES = mapOf(
        ".html" to "text/html; charset=utf-8", ".htm" to "text/html; charset=utf-8", ".js" to "text/javascript; charset=utf-8", ".mjs" to "text/javascript; charset=utf-8",
        ".css" to "text/css; charset=utf-8", ".json" to "application/json; charset=utf-8", ".svg" to "image/svg+xml", ".png" to "image/png", ".jpg" to "image/jpeg",
        ".jpeg" to "image/jpeg", ".gif" to "image/gif", ".webp" to "image/webp", ".ico" to "image/x-icon", ".woff" to "font/woff", ".woff2" to "font/woff2", ".ttf" to "font/ttf",
        ".wasm" to "application/wasm", ".txt" to "text/plain; charset=utf-8", ".md" to "text/plain; charset=utf-8", ".csv" to "text/csv; charset=utf-8", ".glb" to "model/gltf-binary",
        ".bin" to "application/octet-stream", ".pbf" to "application/x-protobuf", ".mp3" to "audio/mpeg", ".wav" to "audio/wav", ".mp4" to "video/mp4",
    )

    /** = appscheme.js SECRET: dot-files and known secret names are never served. */
    val SECRET = Regex("(^|/)(\\.[^/]*|anonymise\\.map\\.json|[^/]*credentials[^/]*\\.json|secrets\\.bin|oauth-clients\\.json|[^/]*\\.pem|[^/]*\\.key)$", RegexOption.IGNORE_CASE)

    fun host(id: String) = "$id.$DOMAIN"

    fun byHost(host: String?, apps: List<DeskApp> = DeskApps.ALL): DeskApp? =
        host?.lowercase()?.removeSuffix(".$DOMAIN")?.takeIf { it != host.lowercase() }?.let { id -> apps.firstOrNull { it.id == id } }

    fun type(rel: String): String = TYPES[rel.substringAfterLast('/').let { n -> if ('.' in n) "." + n.substringAfterLast('.').lowercase() else "" }] ?: "application/octet-stream"

    private fun enc(seg: String): String = buildString {
        for (b in seg.toByteArray(Charsets.UTF_8)) {
            val c = b.toInt() and 0xff
            if (c.toChar().isLetterOrDigit() && c < 128 || c.toChar() in "-._~") append(c.toChar()) else append("%" + "%02X".format(c))
        }
    }

    /** The URL a view loads for app [id], or "" when it is not an app. */
    fun urlFor(id: String, apps: List<DeskApp> = DeskApps.ALL): String {
        val a = apps.firstOrNull { it.id == id } ?: return ""
        return "https://${host(a.id)}/" + a.page.split('/').joinToString("/") { enc(it) }
    }

    /** A view of app [id] may stay on its own origin; anything else is refused (https goes to the phone's browser). */
    fun sameApp(id: String, url: String): Boolean = try {
        val u = URI(url)
        u.scheme == "https" && u.host.equals(host(id), ignoreCase = true) && u.port == -1 && u.rawUserInfo == null
    } catch (e: Exception) { false }

    /**
     * appscheme.js decide(), on the phone's origins. Serves a file only when the host is an app's, and the path, after normalising,
     * lies in the app's own folder or in shared/ (a repo-root page alone). Dot-files, secret names, drive letters, NTFS streams and names
     * Windows would normalise (a trailing dot or space) never. [exists]: whether main has the file (the phone's listing), else 404.
     */
    fun decide(url: String, exists: (String) -> Boolean = { true }, apps: List<DeskApp> = DeskApps.ALL): AppDecision {
        val u = try { URI(url) } catch (e: Exception) { return AppDecision(false, 400, "bad url") }
        if (u.scheme != "https") return AppDecision(false, 400, "scheme")
        if (u.port != -1 || u.rawUserInfo != null) return AppDecision(false, 400, "port or user info")
        val app = byHost(u.host, apps) ?: return AppDecision(false, 404, "not an app")
        var rel = (u.path ?: return AppDecision(false, 400, "bad path")).trimStart('/')
        if (rel.isEmpty()) rel = app.page
        if ('\u0000' in rel || ':' in rel || rel.startsWith("\\\\")) return AppDecision(false, 403, "path")
        if (rel.split('/', '\\').any { it != "." && it != ".." && (it.endsWith('.') || it.endsWith(' ')) }) return AppDecision(false, 403, "path")
        // path.resolve(REPO, rel) then path.relative(REPO, …): '/' and '\' both separate, '..' above the repo is outside
        val out = ArrayDeque<String>()
        for (seg in rel.split('/', '\\')) {
            when (seg) {
                "", "." -> {}
                ".." -> { if (out.isEmpty()) return AppDecision(false, 403, "outside the repo"); out.removeLast() }
                else -> out.addLast(seg)
            }
        }
        val back = out.joinToString("/")
        if (back.isEmpty()) return AppDecision(false, 403, "outside the repo")
        if (app.allow.none { a -> a.isEmpty() || (if (a.endsWith("/")) back.startsWith(a) else back == a) }) return AppDecision(false, 403, "outside the app folder")
        if (SECRET.containsMatchIn(back)) return AppDecision(false, 403, "never served")
        if (!exists(back)) return AppDecision(false, 404, "no such file")
        return AppDecision(true, 200, "", back, type(back), app.id)
    }
}

/** One file as GitHub lists it: the git blob sha says whether it changed. */
data class AppEntry(val sha: String, val size: Long)

/** The files the phone keeps for one app (repo-relative path → sha + size). */
data class AppManifest(val files: Map<String, AppEntry>) {
    val bytes: Long get() = files.values.sumOf { it.size }

    fun toJson(): String {
        val f = JSONObject()
        files.forEach { (k, v) -> f.put(k, JSONObject().put("sha", v.sha).put("size", v.size)) }
        return JSONObject().put("kind", KIND).put("files", f).toString()
    }

    companion object {
        const val KIND = "vrg-app-manifest"
        val EMPTY = AppManifest(emptyMap())

        fun parse(json: String?): AppManifest? = try {
            val o = JSONObject(json ?: return null)
            if (o.optString("kind") != KIND) null
            else {
                val fo = o.optJSONObject("files") ?: JSONObject()
                AppManifest(fo.keys().asSequence().associateWith { val e = fo.getJSONObject(it); AppEntry(e.optString("sha"), e.optLong("size")) })
            }
        } catch (e: Exception) { null }
    }
}

/** What to do after listing an app's folders on GitHub. */
sealed interface AppStep {
    /** The phone's copies are main's. */
    data object Fresh : AppStep
    /** Download [fetch] (the page first), delete [drop]; [remote] is main's state of the listed folders. */
    data class Download(val remote: Map<String, AppEntry>, val fetch: List<String>, val drop: List<String>) : AppStep {
        fun bytes(): Long = fetch.sumOf { remote[it]?.size ?: 0L }
    }
    /** No answer from GitHub: open the phone's copy if there is one. */
    data object Offline : AppStep
    /** GitHub answered and main has no such page (the app moved: the catalog on the phone is older than main). */
    data object Missing : AppStep
}

object AppSync {
    const val BRANCH = "main"

    private fun enc(rel: String) = rel.split('/').joinToString("/") { java.net.URLEncoder.encode(it, "UTF-8").replace("+", "%20") }

    /** The contents API listing of one repo folder ("" = the root). */
    fun listing(repoPath: String, dir: String) = "$repoPath/contents${if (dir.isEmpty()) "" else "/" + enc(dir)}?ref=$BRANCH"

    /** The contents API path of one file. */
    fun contents(repoPath: String, rel: String) = "$repoPath/contents/${enc(rel)}?ref=$BRANCH"

    /** The folders to list for [app]: the page's, and the folder of every other file the phone keeps for it. */
    fun dirs(app: DeskApp, keep: Collection<String>): List<String> =
        (keep + app.page).map { it.substringBeforeLast('/', "") }.distinct().sorted()

    /** One folder's listing → its files (repo-relative path → sha + size), or null when it is not a listing. */
    fun parseListing(json: String, dir: String): Map<String, AppEntry>? = try {
        val arr = JSONArray(json)
        (0 until arr.length()).map { arr.getJSONObject(it) }.filter { it.optString("type") == "file" }
            .associate { (if (dir.isEmpty()) "" else "$dir/") + it.getString("name") to AppEntry(it.getString("sha"), it.optLong("size")) }
    } catch (e: Exception) { null }

    /**
     * [local]: the phone's manifest; [have]: the files on the phone with their bytes; [remote]: main's files in the listed folders, null
     * when a listing failed ([answered] false) or a folder is gone. Every kept file is checked: changed → fetched, gone → dropped.
     */
    fun decide(app: DeskApp, local: AppManifest?, have: Map<String, Long>, remote: Map<String, AppEntry>?, answered: Boolean): AppStep {
        if (!answered) return AppStep.Offline
        if (remote == null || app.page !in remote) return AppStep.Missing
        val mine = local?.files ?: emptyMap()
        val keep = (mine.keys + app.page).filter { it in remote }
        val fetch = keep.filter { rel -> mine[rel]?.sha != remote.getValue(rel).sha || have[rel] != remote.getValue(rel).size }
            .distinct().sortedWith(compareBy<String> { if (it == app.page) 0 else 1 }.thenBy { it })
        val drop = (mine.keys + have.keys).filter { it !in remote }.distinct().sorted()
        val wanted = remote.filterKeys { it in keep }
        return if (fetch.isEmpty() && drop.isEmpty()) AppStep.Fresh else AppStep.Download(wanted, fetch, drop)
    }
}

/** The app WebView's network rule: a GET to an artifact-style CDN may go out (fonts, a library); everything else is the app's own. */
object AppWeb {
    fun mayLoad(scheme: String?, host: String?, method: String?): Boolean = ArchiveWeb.mayLoad(scheme, host, method)
}
